-- Sinh tự động từ src/data/products.json + src/data/productDetails.js
-- Chạy SAU khi đã chạy schema.sql và rls-policies.sql.

insert into products (
  slug, name, category, crop_types, package_unit, form, price, original_price,
  image, images, short_description, ingredients, usage_instructions, usage_needs, tags, in_stock,
  overview, ingredient_items, ingredient_note, benefit_items, usage_steps, dosage_table,
  storage_items, warning_note, quick_info, benefits, suitable_when, specification
) values (
  'magie-bo-kem-no1', 'Magie Bo Kẽm No.1', 'phan-bon-la', '["lua","rau-mau","cay-an-trai","hoa-kieng","cay-cong-nghiep"]'::jsonb, 'Gói 500g', 'bot', 72000, null,
  '/products/cards/magie-bo-kem-no1-card.png', '["/products/magie-bo-kem-no1/img-1.png","/products/magie-bo-kem-no1/img-2.jpg","/products/magie-bo-kem-no1/img-3.jpg","/products/magie-bo-kem-no1/img-4.jpg","/products/magie-bo-kem-no1/img-5.jpg","/products/magie-bo-kem-no1/img-6.jpg","/products/magie-bo-kem-no1/img-7.jpg","/products/magie-bo-kem-no1/img-8.jpg"]'::jsonb, 'Phân bón lá trung vi lượng giúp lớn trái, đẹp màu, ra rễ mạnh và xanh dày lá.', 'Magie (Mg) 0,48%; Bo (B) 500ppm; Kẽm (Zn) 5.000ppm; Sắt (Fe) 10.000ppm; Mangan (Mn) 5.000ppm; pH H2O: 5; Độ ẩm: 5%', 'Cây lương thực: 10-20g/bình 10 lít hoặc 10-20ml/bình 8 lít. Rau màu: 5-10g/bình 8 lít. Cây ăn quả & cây công nghiệp: 10-20g/bình 8 lít. Hoa kiểng: 5-10g/bình 8 lít. Phun định kỳ 7-10 ngày/lần, liều lượng điều chỉnh theo hiện trạng cây trồng, mùa vụ và đất đai.', '["ra-re","xanh-la","nuoi-trai","phuc-hoi-cay-yeu"]'::jsonb, '["ban-chay"]'::jsonb, false,
  'Magie Bo Kẽm No.1 là phân bón lá trung vi lượng dạng bột hòa tan, hỗ trợ cây trồng bổ sung các nguyên tố vi lượng thiết yếu như Magie, Bo, Kẽm, Sắt và Mangan — những yếu tố đóng vai trò quan trọng trong quá trình sinh trưởng, ra hoa, đậu trái và tạo màu sắc trái.

Sản phẩm phù hợp cho nhiều nhóm cây trồng, đặc biệt trong các giai đoạn cây ra hoa, đậu trái, phát triển lá non và khi cây có biểu hiện thiếu vi lượng như lá vàng, trái nhỏ, đọt xoắn hoặc lá mỏng nhạt màu.', '[{"label":"Magie (Mg)","value":"0,48%"},{"label":"Bo (B)","value":"500 ppm"},{"label":"Kẽm (Zn)","value":"5.000 ppm"},{"label":"Sắt (Fe)","value":"10.000 ppm"},{"label":"Mangan (Mn)","value":"5.000 ppm"},{"label":"pH H₂O","value":"5"},{"label":"Độ ẩm","value":"5%"}]'::jsonb, 'Thông tin thành phần được trình bày theo công bố trên bao bì sản phẩm.', '["Hỗ trợ lớn trái, đẹp màu và cải thiện chất lượng quả.","Góp phần kích thích để nhánh, sai hoa và đậu trái nhiều hơn.","Giúp chồi lá mập, hạn chế hiện tượng đọt xoắn và chùn đọt.","Hỗ trợ lá xanh dày, mượt lá và tăng khả năng quang hợp.","Góp phần kích thích ra rễ và phát triển bộ rễ khỏe mạnh.","Hỗ trợ cây phục hồi trong giai đoạn thiếu vi lượng hoặc sau stress."]'::jsonb, '["Pha Magie Bo Kẽm No.1 với nước sạch theo liều lượng khuyến cáo trên bao bì.","Lắc hoặc khuấy đều dung dịch trước khi phun.","Phun đều lên mặt lá, mặt dưới lá và phần ngọn cây vào buổi sáng sớm hoặc chiều mát.","Phun định kỳ 7–10 ngày/lần hoặc điều chỉnh theo tình trạng cây thực tế.","Tránh phun khi trời mưa, nắng gắt hoặc nhiệt độ quá cao trong ngày."]'::jsonb, '[{"crop":"Cây lương thực","dosage":"10–20g / bình 10 lít"},{"crop":"Rau màu","dosage":"5–10g / bình 8 lít"},{"crop":"Cây ăn quả & cây công nghiệp","dosage":"10–20g / bình 8 lít"},{"crop":"Hoa kiểng","dosage":"5–10g / bình 8 lít"}]'::jsonb,
  '["Bảo quản nơi khô ráo, thoáng mát.","Tránh ánh nắng trực tiếp.","Đậy kín nắp sau khi mở hoặc sau khi sử dụng.","Không để sản phẩm tiếp xúc trực tiếp với nước khi chưa pha.","Để xa tầm tay trẻ em và vật nuôi.","Không bảo quản gần thực phẩm, nguồn nước sinh hoạt hoặc hóa chất không tương thích."]'::jsonb, 'Hiệu quả sử dụng sản phẩm có thể thay đổi tùy theo loại cây, tình trạng đất, điều kiện thời tiết, kỹ thuật canh tác và cách sử dụng thực tế. Khách hàng nên đọc kỹ hướng dẫn trên bao bì trước khi sử dụng.

Thông tin trên website chỉ có tính chất tham khảo và không thay thế hướng dẫn chính thức trên bao bì sản phẩm.', '{"thanhPhan":"Mg, Bo, Kẽm, Fe, Mn","xuatXu":"Việt Nam","dang":"Bột hòa tan","congDung":"Lớn trái, đẹp màu, ra rễ","baoQuan":"Nơi khô ráo, thoáng mát"}'::jsonb, '[{"icon":"Leaf","title":"Lá xanh dày, mượt lá","text":"Hỗ trợ bổ sung Magie và vi lượng giúp lá xanh dày, mượt và tăng hiệu quả quang hợp."},{"icon":"Sun","title":"Lớn trái, đẹp màu","text":"Góp phần cải thiện kích thước, màu sắc và chất lượng trái thông qua bổ sung Kẽm và Bo."},{"icon":"Sprout","title":"Ra rễ, đẻ nhánh","text":"Hỗ trợ phát triển bộ rễ và kích thích đẻ nhánh, sai hoa trong giai đoạn sinh trưởng."},{"icon":"Shield","title":"Hạn chế thiếu vi lượng","text":"Phù hợp khi cây có dấu hiệu đọt xoắn, chùn đọt, vàng lá hoặc thiếu khoáng vi lượng."}]'::jsonb, '[{"icon":"AlertCircle","title":"Cây có đọt xoắn","desc":"Hỗ trợ khi cây có hiện tượng đọt xoắn hoặc chùn đọt do thiếu vi lượng."},{"icon":"Leaf","title":"Lá vàng, bạc màu","desc":"Phù hợp khi lá cây có dấu hiệu vàng nhạt hoặc thiếu dinh dưỡng vi lượng."},{"icon":"Sun","title":"Trái nhỏ, màu nhạt","desc":"Hỗ trợ giai đoạn nuôi trái khi trái chậm lớn hoặc màu sắc chưa đẹp."},{"icon":"Sprout","title":"Cây ít hoa, đậu ít","desc":"Phù hợp khi cây ra hoa kém hoặc tỉ lệ đậu trái thấp hơn bình thường."},{"icon":"Zap","title":"Sau giai đoạn stress","desc":"Giúp bổ sung vi lượng cho cây sau thời kỳ chịu hạn, ngập hoặc sâu bệnh."}]'::jsonb, '{"nhomSanPham":"Phân bón lá","quyCach":"Gói 500g","dangSanPham":"Bột hòa tan","xuatXu":"Việt Nam"}'::jsonb
)
on conflict (slug) do nothing;

insert into products (
  slug, name, category, crop_types, package_unit, form, price, original_price,
  image, images, short_description, ingredients, usage_instructions, usage_needs, tags, in_stock,
  overview, ingredient_items, ingredient_note, benefit_items, usage_steps, dosage_table,
  storage_items, warning_note, quick_info, benefits, suitable_when, specification
) values (
  'ph-balance-humate-79', 'pH Balance - Humate 79 Grown', 'phan-bon-re', '["lua","rau-mau","cay-an-trai","hoa-kieng","cay-cong-nghiep"]'::jsonb, 'Hũ 1kg', 'hat', 127000, null,
  '/products/cards/ph-balance-humate-79-card.png', '["/products/ph-balance-humate-79/gallery/img-1.png","/products/ph-balance-humate-79/gallery/img-2.png","/products/ph-balance-humate-79/gallery/img-3.png","/products/ph-balance-humate-79/gallery/img-4.png","/products/ph-balance-humate-79/gallery/img-5.png","/products/ph-balance-humate-79/gallery/img-6.png","/products/ph-balance-humate-79/gallery/img-7.png","/products/ph-balance-humate-79/gallery/img-8.png","/products/ph-balance-humate-79/gallery/img-9.png","/products/ph-balance-humate-79/gallery/img-10.png"]'::jsonb, 'Phân bón sinh học nâng pH, cải tạo đất, kích thích ra rễ và phục hồi cây sau thu hoạch.', 'Axit Humic (C): 22,6%; pH H2O: 5; Độ ẩm: 30%', 'Pha loãng theo hướng dẫn trên bao bì, tưới gốc hoặc phun định kỳ để nâng pH, cân bằng pH đất, cải tạo đất, kích thích bộ rễ phát triển và phục hồi cây sau thu hoạch.', '["ra-re","cai-tao-dat","phuc-hoi-cay-yeu"]'::jsonb, '["moi","ban-chay"]'::jsonb, true,
  'pH Balance - Humate 79 Grown là sản phẩm phân bón sinh học hỗ trợ nâng pH đất, cải tạo đất và kích thích bộ rễ phát triển. Sản phẩm phù hợp cho nhiều nhóm cây trồng, đặc biệt trong các trường hợp đất có dấu hiệu chai cứng, cây sinh trưởng kém hoặc cần phục hồi sau thu hoạch.

Với thành phần Axit Humic 22,6%, sản phẩm góp phần cải thiện cấu trúc đất, hỗ trợ trao đổi dinh dưỡng và tăng khả năng hấp thu của bộ rễ trong nhiều điều kiện đất và loại cây khác nhau.', '[{"label":"Axit Humic (C)","value":"22,6%"},{"label":"pH H₂O","value":"5"},{"label":"Độ ẩm","value":"30%"}]'::jsonb, 'Thông tin thành phần được trình bày theo công bố trên bao bì sản phẩm.', '["Hỗ trợ nâng pH và cân bằng môi trường đất phù hợp cho cây trồng.","Góp phần cải tạo đất, hỗ trợ đất tơi xốp và thông thoáng hơn.","Kích thích phát triển rễ non, rễ tơ và tăng diện tích hấp thu của bộ rễ.","Hỗ trợ nhú đọt, ra chồi nhanh và phát đọt mạnh trong giai đoạn sinh trưởng.","Góp phần phục hồi cây sau thu hoạch hoặc sau giai đoạn suy yếu.","Hỗ trợ tăng sức đề kháng tự nhiên của cây trồng."]'::jsonb, '["Pha loãng pH Balance - Humate 79 Grown với nước tưới theo hướng dẫn trên bao bì.","Tưới đều quanh vùng gốc hoặc khu vực rễ hoạt động của cây.","Sử dụng định kỳ tùy theo tình trạng đất và giai đoạn sinh trưởng của cây.","Nên tưới vào buổi sáng sớm hoặc chiều mát để tránh bay hơi nhanh.","Có thể phối hợp với quy trình chăm sóc đất hiện tại theo hướng dẫn kỹ thuật."]'::jsonb, null,
  '["Đậy kín nắp sau khi sử dụng để giữ chất lượng sản phẩm.","Bảo quản nơi khô ráo, thoáng mát.","Tránh ánh nắng trực tiếp.","Đậy kín nắp sau khi mở hoặc sau khi sử dụng.","Không để sản phẩm tiếp xúc trực tiếp với nước khi chưa pha.","Để xa tầm tay trẻ em và vật nuôi.","Không bảo quản gần thực phẩm, nguồn nước sinh hoạt hoặc hóa chất không tương thích."]'::jsonb, 'Hiệu quả sử dụng sản phẩm có thể thay đổi tùy theo loại cây, tình trạng đất, điều kiện thời tiết, kỹ thuật canh tác và cách sử dụng thực tế. Khách hàng nên đọc kỹ hướng dẫn trên bao bì trước khi sử dụng.

Thông tin trên website chỉ có tính chất tham khảo và không thay thế hướng dẫn chính thức trên bao bì sản phẩm.', '{"thanhPhan":"Axit Humic 22,6%","xuatXu":"Việt Nam","dang":"Sinh học (hạt)","congDung":"Cải tạo đất, hỗ trợ ra rễ","baoQuan":"Nơi khô ráo, thoáng mát"}'::jsonb, '[{"icon":"Sprout","title":"Hỗ trợ cải tạo đất","text":"Góp phần làm đất tơi xốp, thông thoáng và thuận lợi hơn cho rễ phát triển."},{"icon":"Leaf","title":"Kích thích phát triển rễ","text":"Hỗ trợ rễ non, rễ tơ và tăng khả năng hấp thu dinh dưỡng của bộ rễ."},{"icon":"Shield","title":"Hỗ trợ phục hồi cây","text":"Phù hợp cho cây sau thu hoạch hoặc cây suy yếu do điều kiện canh tác."},{"icon":"Zap","title":"Dễ kết hợp quy trình","text":"Có thể dùng trong nhiều giai đoạn tùy theo loại cây và hướng dẫn sử dụng."}]'::jsonb, '[{"icon":"AlertCircle","title":"Đất chai, bạc màu","desc":"Hỗ trợ cải thiện độ tơi xốp và môi trường đất quanh vùng rễ."},{"icon":"Sprout","title":"Cây yếu rễ","desc":"Phù hợp khi cây có bộ rễ kém phát triển hoặc hấp thu dinh dưỡng yếu."},{"icon":"Leaf","title":"Cây chậm phục hồi","desc":"Hỗ trợ cây trong giai đoạn phục hồi chậm sau stress hoặc sâu bệnh."},{"icon":"Sun","title":"Sau thu hoạch","desc":"Phù hợp cho cây sau vụ thu hoạch, hỗ trợ phục hồi và chuẩn bị vụ tiếp theo."},{"icon":"Zap","title":"Hấp thu kém","desc":"Góp phần cải thiện khả năng hấp thu khi đất có pH chưa phù hợp."}]'::jsonb, '{"nhomSanPham":"Phân bón rễ / Sinh học","quyCach":"Hũ 1kg","dangSanPham":"Sinh học (hạt)","xuatXu":"Việt Nam"}'::jsonb
)
on conflict (slug) do nothing;

insert into products (
  slug, name, category, crop_types, package_unit, form, price, original_price,
  image, images, short_description, ingredients, usage_instructions, usage_needs, tags, in_stock,
  overview, ingredient_items, ingredient_note, benefit_items, usage_steps, dosage_table,
  storage_items, warning_note, quick_info, benefits, suitable_when, specification
) values (
  'ra-re-no-bui', 'Ra Rễ - Nở Bụi', 'phan-bon-re', '["lua"]'::jsonb, 'Chai 250ml', 'nuoc', 90000, null,
  '/products/cards/ra-re-no-bui-card.png', '["/products/ra-re-no-bui/gallery/img-1.png","/products/ra-re-no-bui/gallery/img-2.png","/products/ra-re-no-bui/gallery/img-3.png","/products/ra-re-no-bui/gallery/img-4.png","/products/ra-re-no-bui/gallery/img-5.png","/products/ra-re-no-bui/gallery/img-6.png","/products/ra-re-no-bui/gallery/img-7.png","/products/ra-re-no-bui/gallery/img-8.png","/products/ra-re-no-bui/gallery/img-9.png","/products/ra-re-no-bui/gallery/img-10.png","/products/ra-re-no-bui/gallery/img-11.png","/products/ra-re-no-bui/gallery/img-12.png","/products/ra-re-no-bui/gallery/img-13.png","/products/ra-re-no-bui/gallery/img-14.png","/products/ra-re-no-bui/gallery/img-15.png"]'::jsonb, 'Phân bón NPK 10-4-4 chuyên dùng cho lúa, giúp ra rễ mạnh, nở bụi nhanh, cứng cây, hạn chế phèn mặn.', 'Đạm tổng số (N): 10%; Lân hữu hiệu (P2O5): 4%; Kali hữu hiệu (K2O): 4%; Độ ẩm: 5%; Tỷ trọng (dạng lỏng): 1,1', 'Cây ăn trái & cây công nghiệp: 0,5-0,8 lít/500 lít nước/1.000m², tưới gốc 3-4 lần/năm vào giai đoạn phát triển thân lá, ra hoa, đậu quả và sau thu hoạch. Rau màu & cây lương thực: 0,5-0,8 lít/550 lít nước/1.000m², tưới gốc 3 đợt: 10-15, 25-30 và 40-45 ngày sau gieo sạ. Ngưng bón trước thu hoạch 5-7 ngày.', '["ra-re","cai-tao-dat","xanh-la"]'::jsonb, '["ban-chay"]'::jsonb, true,
  'Ra Rễ - Nở Bụi là phân bón NPK 10-4-4 dạng lỏng, chuyên dùng cho cây lúa. Sản phẩm hỗ trợ ra rễ mạnh, đẻ nhánh nhanh, cứng cây và giúp cây lúa hấp thu dinh dưỡng hiệu quả hơn trong giai đoạn đầu sinh trưởng.

Sản phẩm sử dụng nguyên liệu ngoại nhập, được pha chế phù hợp với đặc điểm đất và khí hậu Việt Nam. Phù hợp cho các vùng đất phèn, mặn hoặc khi bộ rễ cây lúa cần được kích thích phục hồi và phát triển.', '[{"label":"Đạm tổng số (N)","value":"10%"},{"label":"Lân hữu hiệu (P₂O₅)","value":"4%"},{"label":"Kali hữu hiệu (K₂O)","value":"4%"},{"label":"Độ ẩm (dạng rắn)","value":"5%"},{"label":"Tỷ trọng (dạng lỏng)","value":"1,1"}]'::jsonb, 'Phân bón NPK 10-4-4 K4P. Sử dụng nguyên liệu ngoại nhập.', '["Hỗ trợ lúa ra rễ mạnh và phục hồi bộ rễ bị tổn thương trong đất phèn mặn.","Góp phần kích thích đẻ nhánh nhanh, nở bụi sớm và cứng cây.","Hỗ trợ giải độc hữu cơ và giảm thiểu ảnh hưởng của phèn mặn.","Giúp cân bằng pH trong điều kiện đất phèn hoặc nhiễm mặn.","Hỗ trợ dòng mạp, trổ tập trung và vào gạo nhanh hơn.","Giúp lá lúa xanh mướt, hạn chế vàng lá và sinh trưởng đồng đều."]'::jsonb, '["Lắc đều chai Ra Rễ - Nở Bụi trước khi sử dụng.","Pha với nước tưới theo tỉ lệ khuyến cáo trên bao bì sản phẩm.","Tưới đều vào gốc và vùng rễ hoạt động của cây lúa.","Áp dụng đúng giai đoạn (xem bảng liều lượng phía dưới) để đạt hiệu quả tốt nhất.","Ngừng sử dụng trước thu hoạch ít nhất 5–7 ngày."]'::jsonb, '[{"crop":"Cây ăn trái & cây công nghiệp","dosage":"0,5–0,8 lít / 500 lít nước / 1.000m², tưới 3–4 lần/năm"},{"crop":"Rau màu & cây lương thực","dosage":"0,5–0,8 lít / 550 lít nước / 1.000m², tưới 3 đợt: 10–15, 25–30 và 40–45 ngày sau sạ"}]'::jsonb,
  '["Bảo quản nơi khô ráo, thoáng mát.","Tránh ánh nắng trực tiếp.","Đậy kín nắp sau khi mở hoặc sau khi sử dụng.","Không để sản phẩm tiếp xúc trực tiếp với nước khi chưa pha.","Để xa tầm tay trẻ em và vật nuôi.","Không bảo quản gần thực phẩm, nguồn nước sinh hoạt hoặc hóa chất không tương thích.","Lắc đều trước khi sử dụng."]'::jsonb, 'Hiệu quả sử dụng sản phẩm có thể thay đổi tùy theo loại cây, tình trạng đất, điều kiện thời tiết, kỹ thuật canh tác và cách sử dụng thực tế. Khách hàng nên đọc kỹ hướng dẫn trên bao bì trước khi sử dụng.

Thông tin trên website chỉ có tính chất tham khảo và không thay thế hướng dẫn chính thức trên bao bì sản phẩm.', '{"thanhPhan":"NPK 10-4-4 K4P","xuatXu":"Việt Nam","dang":"Dạng lỏng","congDung":"Ra rễ, đẻ nhánh, hạ phèn","baoQuan":"Nơi khô ráo, lắc đều trước dùng"}'::jsonb, '[{"icon":"Sprout","title":"Ra rễ mạnh, bộ rễ khỏe","text":"Hỗ trợ lúa phát triển bộ rễ tốt, giúp cây hấp thu dinh dưỡng hiệu quả hơn."},{"icon":"Leaf","title":"Đẻ nhánh, nở bụi nhanh","text":"Góp phần kích thích cây lúa đẻ nhánh sớm và nở bụi đồng đều, cứng cây."},{"icon":"Shield","title":"Giải độc, hạ phèn","text":"Hỗ trợ cây trong điều kiện đất phèn mặn, giúp cây chịu đựng tốt hơn."},{"icon":"Zap","title":"Xanh mướt, hạn chế vàng lá","text":"Góp phần giữ lá xanh mướt, hạn chế hiện tượng vàng lá và vàng chóp."}]'::jsonb, '[{"icon":"Sprout","title":"Lúa mới sạ","desc":"Phù hợp giai đoạn đầu sau sạ, hỗ trợ cây bén rễ và ra rễ nhanh."},{"icon":"Leaf","title":"Đẻ nhánh chậm","desc":"Hỗ trợ khi lúa đẻ nhánh chậm hoặc nở bụi kém so với kỳ vọng."},{"icon":"AlertCircle","title":"Đất phèn, mặn","desc":"Góp phần giải độc và hỗ trợ cây trong điều kiện đất phèn hoặc nhiễm mặn."},{"icon":"Sun","title":"Cây yếu, lá nhạt màu","desc":"Phù hợp khi cây lúa yếu, lá xanh nhạt hoặc sinh trưởng không đều."},{"icon":"Zap","title":"Sau stress ngập/hạn","desc":"Hỗ trợ cây phục hồi sau khi gặp điều kiện bất thuận như ngập úng, hạn hán."}]'::jsonb, '{"nhomSanPham":"Phân bón rễ / NPK","quyCach":"Chai 250ml","dangSanPham":"Dạng lỏng (nước)","xuatXu":"Việt Nam"}'::jsonb
)
on conflict (slug) do nothing;

insert into products (
  slug, name, category, crop_types, package_unit, form, price, original_price,
  image, images, short_description, ingredients, usage_instructions, usage_needs, tags, in_stock,
  overview, ingredient_items, ingredient_note, benefit_items, usage_steps, dosage_table,
  storage_items, warning_note, quick_info, benefits, suitable_when, specification
) values (
  'vo-gao-nhanh', 'Vô Gạo Nhanh', 'phan-bon-la', '["lua"]'::jsonb, 'Chai 250ml', 'nuoc', 83000, null,
  '/products/cards/vo-gao-nhanh-card.png', '["/products/vo-gao-nhanh/gallery/img-1.png","/products/vo-gao-nhanh/gallery/img-2.png","/products/vo-gao-nhanh/gallery/img-3.png","/products/vo-gao-nhanh/gallery/img-4.png","/products/vo-gao-nhanh/gallery/img-5.png","/products/vo-gao-nhanh/gallery/img-6.png","/products/vo-gao-nhanh/gallery/img-7.png","/products/vo-gao-nhanh/gallery/img-8.png","/products/vo-gao-nhanh/gallery/img-9.png","/products/vo-gao-nhanh/gallery/img-10.png"]'::jsonb, 'Phân bón lá chuyên dùng cho lúa, giúp xanh dày lá, chắc cứng cổ cây, hạt to sáng bóng, hạn chế đổ ngã.', 'Phân bón hỗn hợp NPK - phân bón lá LM 17', 'Cây lương thực: 12-15ml/1.000m²/lần, bón vào thời kỳ đẻ nhánh và phân hóa đòng, hoa. Cây công nghiệp, ăn trái: 150-200ml/gốc/lần, bón vào đầu, giữa và sau mùa mưa. Giai đoạn làm bông: pha 250ml/200 lít nước. Giai đoạn mang trái: pha 150-200ml/200 lít nước, tưới vào khu vực mầm hoa non mới hình thành.', '["xanh-la","nuoi-trai","duong-cay"]'::jsonb, '["moi","ban-chay"]'::jsonb, true,
  'Vô Gạo Nhanh là phân bón NPK dạng lỏng (Phân bón lúa LM 17), chuyên dùng cho cây lúa. Sản phẩm hỗ trợ lá xanh dày, cứng cổ cây, trổ đòng thoát và giúp hạt lúa to đều, sáng bóng, ngăn chặn nguy cơ đổ ngã.

Sản phẩm phù hợp sử dụng trong nhiều giai đoạn sinh trưởng của cây lúa — từ đẻ nhánh, làm đòng, trổ bông đến giai đoạn vào chắc hạt — giúp nâng cao chất lượng và năng suất lúa gạo.', '[{"label":"Loại phân bón","value":"NPK hỗn hợp — Phân bón lúa LM 17"}]'::jsonb, 'Thành phần chi tiết theo công bố trên bao bì sản phẩm. Vui lòng tham khảo nhãn chai trước khi sử dụng.', '["Hỗ trợ lá xanh dày, tăng diện tích và hiệu quả quang hợp.","Góp phần chín cứng cổ cây, tăng độ cứng thân và hạn chế đổ ngã.","Hỗ trợ trổ đòng đồng loạt, thoát đòng nhanh và đồng đều trong ruộng.","Góp phần tạo hạt to đều, sáng bóng và tăng tỷ lệ vào chắc.","Hỗ trợ nâng cao năng suất lúa trong điều kiện canh tác bình thường."]'::jsonb, '["Lắc đều chai Vô Gạo Nhanh trước khi sử dụng.","Pha với nước sạch theo liều lượng khuyến cáo trên bao bì sản phẩm.","Phun đều lên lá hoặc tưới vào gốc tùy theo giai đoạn sinh trưởng.","Sử dụng đúng thời điểm (đẻ nhánh, làm đòng, trổ bông) để đạt hiệu quả tối ưu.","Tránh phun khi trời mưa hoặc nắng gắt trong ngày."]'::jsonb, '[{"crop":"Cây lương thực (phun lá)","dosage":"12–15ml / 1.000m² / lần, giai đoạn đẻ nhánh và phân hóa đòng"},{"crop":"Cây công nghiệp, ăn trái","dosage":"150–200ml / gốc / lần, đầu, giữa và sau mùa mưa"},{"crop":"Giai đoạn làm bông","dosage":"Pha 250ml / 200 lít nước"},{"crop":"Giai đoạn mang trái","dosage":"Pha 150–200ml / 200 lít nước"}]'::jsonb,
  '["Bảo quản nơi khô ráo, thoáng mát.","Tránh ánh nắng trực tiếp.","Đậy kín nắp sau khi mở hoặc sau khi sử dụng.","Không để sản phẩm tiếp xúc trực tiếp với nước khi chưa pha.","Để xa tầm tay trẻ em và vật nuôi.","Không bảo quản gần thực phẩm, nguồn nước sinh hoạt hoặc hóa chất không tương thích.","Lắc đều trước khi sử dụng."]'::jsonb, 'Hiệu quả sử dụng sản phẩm có thể thay đổi tùy theo loại cây, tình trạng đất, điều kiện thời tiết, kỹ thuật canh tác và cách sử dụng thực tế. Khách hàng nên đọc kỹ hướng dẫn trên bao bì trước khi sử dụng.

Thông tin trên website chỉ có tính chất tham khảo và không thay thế hướng dẫn chính thức trên bao bì sản phẩm.', '{"thanhPhan":"NPK (Phân bón lúa LM 17)","xuatXu":"Việt Nam","dang":"Dạng lỏng","congDung":"Xanh lá, cứng cây, vào gạo","baoQuan":"Nơi khô ráo, lắc đều trước dùng"}'::jsonb, '[{"icon":"Leaf","title":"Lá xanh dày, quang hợp tốt","text":"Hỗ trợ lá xanh dày, tăng hiệu quả quang hợp và tích lũy dinh dưỡng cho cây lúa."},{"icon":"Shield","title":"Cứng cổ cây, ngăn đổ ngã","text":"Góp phần chín cứng cổ cây, hạn chế tình trạng đổ ngã và thất thoát năng suất."},{"icon":"Sun","title":"Trổ đồng loạt, thoát đòng nhanh","text":"Hỗ trợ trổ bông đồng đều trong toàn ruộng, thoát đòng nhanh và thuận lợi."},{"icon":"Zap","title":"Hạt to đều, sáng bóng","text":"Góp phần giúp hạt lúa vào chắc đều, to sáng và tăng tỷ lệ thương phẩm."}]'::jsonb, '[{"icon":"Sun","title":"Giai đoạn làm đòng","desc":"Phù hợp để sử dụng trong giai đoạn lúa làm đòng, nuôi đòng và trổ bông."},{"icon":"Leaf","title":"Lá mỏng, nhạt màu","desc":"Hỗ trợ khi lá lúa mỏng, màu nhạt hoặc quang hợp kém hiệu quả."},{"icon":"Shield","title":"Cây dễ đổ ngã","desc":"Phù hợp khi cây lúa có thân yếu hoặc ruộng có nguy cơ đổ ngã cao."},{"icon":"Zap","title":"Hạt vào chắc chậm","desc":"Hỗ trợ giai đoạn hạt vào chắc chậm hoặc tỷ lệ lép cao hơn kỳ vọng."},{"icon":"AlertCircle","title":"Ruộng trổ không đều","desc":"Góp phần hỗ trợ ruộng trổ bông đồng loạt và thoát đòng thuận lợi hơn."}]'::jsonb, '{"nhomSanPham":"Phân bón lá / NPK","quyCach":"Chai 250ml","dangSanPham":"Dạng lỏng (nước)","xuatXu":"Việt Nam"}'::jsonb
)
