) values (
  'lun-cay-ruoc-dong', 'Lùn Cây - Rước Đòng', 'npk', '["lua"]'::jsonb, 'Chai 250ml', 'nuoc', 87000, null,
  '/products/cards/lun-cay-ruoc-dong-card.png', '["/products/lun-cay-ruoc-dong/img-1.jpg","/products/lun-cay-ruoc-dong/img-2.jpg","/products/lun-cay-ruoc-dong/img-3.jpg","/products/lun-cay-ruoc-dong/img-4.jpg","/products/lun-cay-ruoc-dong/img-5.jpg","/products/lun-cay-ruoc-dong/img-6.jpg","/products/lun-cay-ruoc-dong/img-7.jpg"]'::jsonb, 'Phân bón NPK chuyên dùng cho lúa, giúp lùn cây cứng thân, dưỡng đòng mập đòng, trổ thoát đồng loạt.', 'Đạm tổng số (N): 4%; Lân hữu hiệu (P2O5): 12%; Kali hữu hiệu (K2O): 10%; Độ ẩm: 5%; Tỷ trọng (dạng lỏng): 1,2', 'Cây lương thực: 12-15 lít dung dịch/1.000m²/lần, bón vào thời kỳ đẻ nhánh và phân hóa đòng, hoa. Cây công nghiệp, ăn trái: 150-200ml/gốc/lần, bón vào đầu, giữa và sau mùa mưa. Giai đoạn làm bông: pha 250ml/200 lít nước. Giai đoạn mang trái: pha 150-200ml/200 lít nước, sử dụng khi các mầm đọt non mới hình thành.', '["duong-cay","ra-hoa","nuoi-trai"]'::jsonb, '["ban-chay"]'::jsonb, true,
  'Lùn Cây - Rước Đòng là phân bón NPK dạng lỏng (Phân bón Lùm 12), chuyên dùng cho cây lúa trong giai đoạn làm đòng và trổ bông. Sản phẩm hỗ trợ ngắn lóng, cứng thân, dưỡng đòng mập và kích thích lúa trổ đồng loạt.

Phù hợp cho vùng canh tác lúa có điều kiện dễ đổ ngã hoặc giai đoạn trổ bông gặp trở ngại. Sản phẩm được phát triển để hỗ trợ tối ưu hiệu quả vụ lúa trong giai đoạn quyết định năng suất.', '[{"label":"Đạm tổng số (N)","value":"4%"},{"label":"Lân hữu hiệu (P₂O₅)","value":"12%"},{"label":"Kali hữu hiệu (K₂O)","value":"10%"},{"label":"Độ ẩm (dạng rắn)","value":"5%"},{"label":"Tỷ trọng (dạng lỏng)","value":"1,2"}]'::jsonb, 'Phân bón NPK — Phân bón Lùm 12. Thông tin theo công bố trên bao bì sản phẩm.', '["Hỗ trợ ngắn lóng, lùn cây và cứng thân lúa để hạn chế đổ ngã.","Góp phần dưỡng đòng, nuôi tim đen và giúp đòng mập khỏe.","Hỗ trợ lúa trổ bông đồng loạt và thoát đòng thuận lợi hơn.","Góp phần tăng số lượng hạt trên bông và cải thiện tỷ lệ chắc hạt.","Hỗ trợ cây đứng lá, mướt lá và hạn chế tình trạng đổ ngã trong giai đoạn trổ."]'::jsonb, '["Lắc đều chai Lùn Cây - Rước Đòng trước khi sử dụng.","Pha với nước sạch theo liều lượng trên bao bì sản phẩm.","Sử dụng đúng thời điểm cây lúa bắt đầu làm đòng hoặc theo hướng dẫn kỹ thuật.","Phun lên lá hoặc tưới gốc tùy theo giai đoạn và loại cây.","Tránh phun khi trời mưa hoặc nhiệt độ quá cao."]'::jsonb, '[{"crop":"Cây lương thực","dosage":"12–15 lít dung dịch / 1.000m² / lần, giai đoạn đẻ nhánh và phân hóa đòng"},{"crop":"Cây công nghiệp, ăn trái","dosage":"150–200ml / gốc / lần, đầu, giữa và sau mùa mưa"},{"crop":"Giai đoạn làm bông","dosage":"Pha 250ml / 200 lít nước"},{"crop":"Giai đoạn mang trái","dosage":"Pha 150–200ml / 200 lít nước, khi mầm đọt non mới hình thành"}]'::jsonb,
  '["Bảo quản nơi khô ráo, thoáng mát.","Tránh ánh nắng trực tiếp.","Đậy kín nắp sau khi mở hoặc sau khi sử dụng.","Không để sản phẩm tiếp xúc trực tiếp với nước khi chưa pha.","Để xa tầm tay trẻ em và vật nuôi.","Không bảo quản gần thực phẩm, nguồn nước sinh hoạt hoặc hóa chất không tương thích.","Lắc đều trước khi sử dụng."]'::jsonb, 'Hiệu quả sử dụng sản phẩm có thể thay đổi tùy theo loại cây, tình trạng đất, điều kiện thời tiết, kỹ thuật canh tác và cách sử dụng thực tế. Khách hàng nên đọc kỹ hướng dẫn trên bao bì trước khi sử dụng.

Thông tin trên website chỉ có tính chất tham khảo và không thay thế hướng dẫn chính thức trên bao bì sản phẩm.', '{"thanhPhan":"NPK 4-12-10 (Lùm 12)","xuatXu":"Việt Nam","dang":"Dạng lỏng","congDung":"Lùn cây, cứng thân, rước đòng","baoQuan":"Nơi khô ráo, lắc đều trước dùng"}'::jsonb, '[{"icon":"Shield","title":"Ngắn lóng, cứng thân","text":"Hỗ trợ ngắn lóng và cứng thân giúp cây lúa vững chắc, hạn chế đổ ngã."},{"icon":"Leaf","title":"Nuôi đòng mập, khỏe","text":"Góp phần dưỡng đòng và nuôi tim đen giúp đòng mập, khỏe và đầy đặn hơn."},{"icon":"Sun","title":"Trổ bông đồng loạt","text":"Hỗ trợ lúa trổ bông đồng đều trong toàn ruộng và thoát đòng thuận lợi."},{"icon":"Zap","title":"Tăng số hạt/bông","text":"Góp phần cải thiện số hạt trên bông và tỷ lệ hạt chắc cho năng suất tốt hơn."}]'::jsonb, '[{"icon":"Shield","title":"Cây dễ đổ ngã","desc":"Phù hợp khi lúa có thân yếu, lóng dài hoặc ruộng có nguy cơ đổ ngã cao."},{"icon":"Sun","title":"Giai đoạn làm đòng","desc":"Sử dụng đúng thời điểm cây lúa bắt đầu làm đòng để đạt hiệu quả tốt nhất."},{"icon":"Leaf","title":"Đòng yếu, ít hạt","desc":"Hỗ trợ khi đòng phát triển yếu hoặc số hạt/bông thấp hơn kỳ vọng."},{"icon":"AlertCircle","title":"Trổ không đồng đều","desc":"Góp phần khắc phục tình trạng lúa trổ không đều hoặc thoát đòng gặp trở ngại."},{"icon":"Zap","title":"Muốn nâng năng suất","desc":"Phù hợp cho ruộng muốn cải thiện tỷ lệ chắc hạt và năng suất vụ lúa."}]'::jsonb, '{"nhomSanPham":"Phân bón NPK","quyCach":"Chai 250ml","dangSanPham":"Dạng lỏng (nước)","xuatXu":"Việt Nam"}'::jsonb
)
on conflict (slug) do nothing;

insert into products (
  slug, name, category, crop_types, package_unit, form, price, original_price,
  image, images, short_description, ingredients, usage_instructions, usage_needs, tags, in_stock,
  overview, ingredient_items, ingredient_note, benefit_items, usage_steps, dosage_table,
  storage_items, warning_note, quick_info, benefits, suitable_when, specification
) values (
  'loang-trai-tham-sau', 'Loang Trải Thấm Sâu', 'phan-bon-re', '["lua","rau-mau","cay-an-trai","hoa-kieng","cay-cong-nghiep"]'::jsonb, 'Chai 100ml', 'nuoc', 84550, 89000,
  '/products/cards/loang-trai-tham-sau-card.png', '["/products/loang-trai-tham-sau/gallery/img-1.png","/products/loang-trai-tham-sau/gallery/img-2.png","/products/loang-trai-tham-sau/gallery/img-3.png","/products/loang-trai-tham-sau/gallery/img-4.png","/products/loang-trai-tham-sau/gallery/img-5.png","/products/loang-trai-tham-sau/gallery/img-6.png","/products/loang-trai-tham-sau/gallery/img-7.png","/products/loang-trai-tham-sau/gallery/img-8.png","/products/loang-trai-tham-sau/gallery/img-9.png"]'::jsonb, 'Chất hỗ trợ lan trải và thấm sâu, giúp phân bón thẩm thấu đều vào đất và rễ cây, tăng hiệu quả hấp thu dưỡng chất.', 'Chất hoạt động bề mặt sinh học, chất lan trải hữu cơ', 'Pha cùng dung dịch phân bón hoặc thuốc bảo vệ thực vật theo tỉ lệ khuyến cáo trên nhãn. Sử dụng khi tưới gốc hoặc phun lá để tăng hiệu quả thẩm thấu và hấp thu.', '["ra-re","cai-tao-dat","phuc-hoi-cay-yeu"]'::jsonb, '["ban-chay"]'::jsonb, true,
  'Loang Trải Thấm Sâu là chế phẩm dùng trong nông nghiệp (Siêu thấm thấu 30SL), được thiết kế để sử dụng kết hợp cùng phân bón hoặc thuốc bảo vệ thực vật. Sản phẩm hỗ trợ tăng khả năng bám dính, lan trải đều và thấm sâu trên bề mặt lá và cây trồng.

Khi phối hợp với phân bón hoặc BVTV, sản phẩm giúp dung dịch tiếp xúc đều hơn trên toàn bề mặt lá, thấm sâu vào mô cây và tăng hiệu quả hấp thu — góp phần giúp phân bón và thuốc phát huy tốt hơn.', '[{"label":"Surfactant C10 Alcohol Ethoxylate","value":"30%"},{"label":"Phụ gia đặc biệt","value":"Vừa đủ 70%"},{"label":"Tỷ trọng (dạng lỏng)","value":"1,1"},{"label":"Thể tích thực","value":"100ml"},{"label":"Số TCCS","value":"01:2024/LOANGTRAI-TS"}]'::jsonb, 'Chế phẩm dùng trong nông nghiệp — Siêu thấm thấu 30SL. Thông tin theo công bố trên bao bì sản phẩm.', '["Tăng khả năng bám dính của dung dịch phân bón/thuốc BVTV trên bề mặt lá.","Hỗ trợ lan trải đều, giúp dung dịch phủ đều hơn trên toàn bộ bề mặt cây.","Kích nở khí không, hỗ trợ thấm sâu vào mô lá và cơ quan hấp thu của cây.","Góp phần tăng hiệu quả hấp thu phân bón và thuốc BVTV.","Giúp tiết kiệm lượng phân bón/thuốc nhờ phân bố đều hơn trên cây trồng.","An toàn cho cây trồng và môi trường khi sử dụng đúng liều lượng."]'::jsonb, '["Lắc đều chai Loang Trải Thấm Sâu trước khi sử dụng.","Pha 100ml cho mỗi 300 lít nước (hoặc theo hướng dẫn trên bao bì).","Phối hợp cùng dung dịch phân bón hoặc thuốc BVTV cần sử dụng.","Phun ướt đều toàn bộ cây trồng — mặt lá, mặt dưới lá và thân cây.","Sử dụng vào buổi sáng sớm hoặc chiều mát để tăng hiệu quả hấp thu."]'::jsonb, '[{"crop":"Phối với phân bón / thuốc BVTV","dosage":"100ml / 300 lít nước, phun ướt đều cây trồng"}]'::jsonb,
  '["Bảo quản nơi khô ráo, thoáng mát, tránh ánh nắng trực tiếp.","Đậy kín nắp chai sau khi sử dụng.","Tránh xa tầm tay trẻ em và nguồn thực phẩm.","Sử dụng vào buổi sáng sớm hoặc chiều mát.","Không bảo quản gần nguồn nước sinh hoạt hoặc hóa chất không tương thích."]'::jsonb, 'Hiệu quả sử dụng sản phẩm có thể thay đổi tùy theo loại cây, tình trạng đất, điều kiện thời tiết, kỹ thuật canh tác và cách sử dụng thực tế. Khách hàng nên đọc kỹ hướng dẫn trên bao bì trước khi sử dụng.

Thông tin trên website chỉ có tính chất tham khảo và không thay thế hướng dẫn chính thức trên bao bì sản phẩm.', '{"thanhPhan":"Surfactant C10 AE 30%","xuatXu":"Việt Nam","dang":"Dung dịch (lỏng)","congDung":"Tăng bám dính, thấm sâu","baoQuan":"Nơi khô ráo, đậy kín sau dùng"}'::jsonb, '[{"icon":"Droplets","title":"Tăng bám dính","text":"Hỗ trợ phân bón và thuốc BVTV bám chặt hơn trên bề mặt lá, giảm trôi rửa do mưa."},{"icon":"Zap","title":"Loang trải đều","text":"Giúp dung dịch phủ đều toàn bộ bề mặt cây, không bỏ sót vùng tiếp xúc quan trọng."},{"icon":"Sprout","title":"Thấm sâu hiệu quả","text":"Hỗ trợ dung dịch thấm sâu vào mô lá và cơ quan hấp thu của cây trồng."},{"icon":"Leaf","title":"Tiết kiệm chi phí","text":"Giúp tối ưu hiệu quả của phân bón và thuốc đã dùng, có thể giảm lượng cần thiết."}]'::jsonb, '[{"icon":"Droplets","title":"Phun trong mùa mưa","desc":"Giúp tăng bám dính của dung dịch khi thời tiết dễ bị rửa trôi."},{"icon":"Leaf","title":"Lá trơn, khó thấm","desc":"Phù hợp với các loại cây có bề mặt lá trơn, dung dịch dễ chảy đi."},{"icon":"Zap","title":"Muốn tăng hiệu quả","desc":"Khi muốn tối ưu hiệu quả của phân bón hoặc thuốc BVTV đang sử dụng."},{"icon":"Sun","title":"Phun diện tích lớn","desc":"Phù hợp khi phun trên diện tích lớn, cần đảm bảo phủ đều mà không tăng lượng thuốc."},{"icon":"Shield","title":"Cây hấp thu kém","desc":"Hỗ trợ khi cây có dấu hiệu hấp thu chậm hoặc phân bón không phát huy hiệu quả."}]'::jsonb, '{"nhomSanPham":"Chế phẩm nông nghiệp","quyCach":"Chai 100ml","dangSanPham":"Dung dịch lỏng (30SL)","xuatXu":"Việt Nam"}'::jsonb
)
on conflict (slug) do nothing;

insert into products (
  slug, name, category, crop_types, package_unit, form, price, original_price,
  image, images, short_description, ingredients, usage_instructions, usage_needs, tags, in_stock,
  overview, ingredient_items, ingredient_note, benefit_items, usage_steps, dosage_table,
  storage_items, warning_note, quick_info, benefits, suitable_when, specification
) values (
  'robust', 'Robust Giải Độc Tố Đất', 'huu-co', '["cay-an-trai","cay-cong-nghiep","rau-mau"]'::jsonb, 'Chai 1 Lít', 'nuoc', 117000, 130000,
  '/products/robust/img-1.png', '["/products/robust/gallery/img-1.png","/products/robust/gallery/img-2.png","/products/robust/gallery/img-3.png","/products/robust/gallery/img-4.png","/products/robust/gallery/img-5.png","/products/robust/gallery/img-6.png","/products/robust/gallery/img-7.png","/products/robust/gallery/img-8.png","/products/robust/gallery/img-9.png"]'::jsonb, 'Chế phẩm sinh học giải độc tố đất, kháng khuẩn, giữ ẩm, khử phèn và tạo hệ vi sinh vật có lợi phát triển.', 'VSV phân giải Xenllulo 1x10⁸ CFU/ml; Nguyên liệu: chuối, trứng, sữa; Vi sinh chuyên dùng: Bacillus, Trichoderma, Enzyme', 'Cây thân gỗ (sầu riêng, chè, cà phê): 1 lít/200-400 lít nước. Cây rau màu, cây thân dây (hồ tiêu, chanh dây, khổ qua, bầu bí, dưa, khoai lang, các loại đậu...): 1 lít/400-600 lít nước. Tưới quanh gốc vào sáng sớm hoặc chiều mát, tưới nước cho đất ẩm trước khi tưới vi sinh để tạo đường dẫn.', '["cai-tao-dat","phuc-hoi-cay-yeu","ra-re"]'::jsonb, '["moi"]'::jsonb, true,
  'ROBUST Giải Độc Tố Đất là chế phẩm sinh học giúp giải độc tố trong đất, cải tạo hệ vi sinh, giữ ẩm và phục hồi bộ rễ khỏe mạnh. Giải pháp sinh học an toàn cho cây trồng và đất canh tác lâu dài, hữu cơ an toàn — lành tính — phù hợp sử dụng cho nhiều loại cây trồng.

Sản phẩm phân giải các độc tố như kim loại nặng, hóa chất tồn dư trong đất, tạo hệ vi sinh làm đất tơi xốp, ổn định pH và có thể dùng để ủ rơm rạ, cám gạo, phân chuồng thành phân bón.', '[{"label":"VSV phân giải Xenllulo","value":"1x10⁸ CFU/ml"},{"label":"Nguyên liệu","value":"Chuối, trứng, sữa"},{"label":"Vi sinh chuyên dùng","value":"Bacillus, Trichoderma, Enzyme"},{"label":"Thể tích thực","value":"1 lít"}]'::jsonb, 'Thông tin thành phần được trình bày theo công bố trên bao bì sản phẩm.', '["Cải tạo đất: phân giải độc tố gồm các chất có hại như kim loại nặng, hóa chất tồn dư trong đất.","Tạo hệ vi sinh làm đất tơi xốp.","Ổn định pH đất (là hiệu ứng phụ đi kèm, không thay thế sản phẩm chuyên biệt cân bằng pH).","Dùng để ủ rơm rạ, cám gạo, phân chuồng... làm phân bón.","Giữ ẩm cho đất, hỗ trợ phục hồi bộ rễ khỏe mạnh."]'::jsonb, '["Lắc đều chai Robust trước khi pha.","Pha theo liều lượng ở bảng dưới tùy nhóm cây trồng.","Tưới nước trước cho cây ẩm ướt nhằm tạo đường dẫn cho vi sinh thẩm thấu.","Tưới đều quanh gốc vào sáng sớm hoặc chiều mát.","Không pha chung với thuốc trừ sâu, thuốc có gốc đồng."]'::jsonb, '[{"crop":"Cây thân gỗ (sầu riêng, chè, cà phê)","dosage":"1 lít / 200–400 lít nước, tưới quanh gốc"},{"crop":"Cây rau màu, cây thân dây (hồ tiêu, chanh dây, khổ qua, bầu bí, dưa, khoai lang, các loại đậu...)","dosage":"1 lít / 400–600 lít nước, tưới quanh gốc"}]'::jsonb,
  '["Nơi khô ráo, thoáng mát, tránh ánh nắng trực tiếp.","Đậy nắp sau khi sử dụng.","Lắc đều trước khi pha.","Hạn sử dụng: 24 tháng kể từ ngày sản xuất, 6 tháng sau khi mở nắp.","Sau khi pha với nước: không để dung dịch quá 7 ngày."]'::jsonb, 'Không pha chung với thuốc trừ sâu hoặc thuốc có gốc đồng. Có thể điều chỉnh liều lượng phù hợp với tình trạng cây trồng, thổ nhưỡng đất canh tác và kinh nghiệm thực tế của người trồng.

Hiệu quả sử dụng sản phẩm có thể thay đổi tùy theo loại cây, tình trạng đất, điều kiện thời tiết, kỹ thuật canh tác và cách sử dụng thực tế. Khách hàng nên đọc kỹ hướng dẫn trên bao bì trước khi sử dụng.

Thông tin trên website chỉ có tính chất tham khảo và không thay thế hướng dẫn chính thức trên bao bì sản phẩm.', '{"thanhPhan":"VSV Xenllulo, Bacillus, Trichoderma","xuatXu":"Việt Nam","quyCach":"Chai 1 Lít","dang":"Dạng lỏng","congDung":"Giải độc đất, khử phèn, tạo hệ vi sinh","baoQuan":"Nơi khô ráo, đậy nắp sau dùng"}'::jsonb, '[{"icon":"Shield","title":"Giải độc tố đất","text":"Phân giải độc tố như kim loại nặng, hóa chất tồn dư giúp đất sạch và an toàn hơn."},{"icon":"Droplets","title":"Giữ ẩm, khử phèn","text":"Giúp đất giữ ẩm tốt hơn và cải thiện môi trường đất chua phèn."},{"icon":"Sprout","title":"Tạo hệ vi sinh có lợi","text":"Góp phần tạo hệ vi sinh làm đất tơi xốp, ổn định pH và thông thoáng hơn."},{"icon":"Leaf","title":"Ủ phân hữu cơ","text":"Có thể dùng để ủ rơm rạ, cám gạo, phân chuồng... thành phân bón hữu cơ."}]'::jsonb, '[{"icon":"AlertCircle","title":"Đất bạc màu, chai cứng","desc":"Phù hợp cho đất bạc màu, nhiễm phèn hoặc chai cứng sau nhiều vụ dùng hóa chất."},{"icon":"Sprout","title":"Đất tồn dư hóa chất","desc":"Hỗ trợ phân giải kim loại nặng và hóa chất tồn dư trong đất canh tác."},{"icon":"Shield","title":"Trước khi vào vụ mới","desc":"Thích hợp cải tạo đất trước khi xuống giống vụ mới, đặc biệt vùng đất phèn, mặn."},{"icon":"Droplets","title":"Đất khô hạn cục bộ","desc":"Hỗ trợ giữ ẩm cho đất trong điều kiện khô hạn quanh vùng rễ."},{"icon":"Leaf","title":"Cần ủ phân hữu cơ","desc":"Phù hợp khi cần ủ rơm rạ, cám gạo hoặc phân chuồng thành phân bón."}]'::jsonb, '{"nhomSanPham":"Chế phẩm sinh học cải tạo đất","quyCach":"Chai 1 Lít","dangSanPham":"Dung dịch lỏng","xuatXu":"Việt Nam"}'::jsonb
)
on conflict (slug) do nothing;

insert into products (
  slug, name, category, crop_types, package_unit, form, price, original_price,
  image, images, short_description, ingredients, usage_instructions, usage_needs, tags, in_stock,
  overview, ingredient_items, ingredient_note, benefit_items, usage_steps, dosage_table,
  storage_items, warning_note, quick_info, benefits, suitable_when, specification
) values (
  'lasting-khang-nam-tuyen-trung', 'Lasting Kháng Nấm - Tuyến Trùng', 'phan-bon-re', '["cay-an-trai","cay-cong-nghiep","rau-mau"]'::jsonb, 'Chai 1 Lít', 'nuoc', 117000, 130000,
  '/products/lasting-khang-nam-tuyen-trung/img-1.png', '["/products/lasting-khang-nam-tuyen-trung/gallery/img-1.png","/products/lasting-khang-nam-tuyen-trung/gallery/img-2.png","/products/lasting-khang-nam-tuyen-trung/gallery/img-3.png","/products/lasting-khang-nam-tuyen-trung/gallery/img-4.png","/products/lasting-khang-nam-tuyen-trung/gallery/img-5.png","/products/lasting-khang-nam-tuyen-trung/gallery/img-6.png","/products/lasting-khang-nam-tuyen-trung/gallery/img-7.png","/products/lasting-khang-nam-tuyen-trung/gallery/img-8.png","/products/lasting-khang-nam-tuyen-trung/gallery/img-9.png"]'::jsonb, 'Chế phẩm sinh học giúp kiểm soát nấm bệnh, tuyến trùng, phát triển bộ rễ khỏe, khử phèn và cải tạo đất.', 'VSV phân giải Xenllulo 1x10⁸ CFU/ml; Vi sinh vật có lợi: Bacillus, Trichoderma, Enzyme; Thảo dược truyền thống', 'Cây thân gỗ (sầu riêng, chè, cà phê): 1 lít/100-200 lít nước, tưới lá và quanh gốc. Cây rau màu, cây thân dây (hồ tiêu, chanh dây, khổ qua, bầu bí, dưa, khoai lang, các loại đậu...): 1 lít/200-400 lít nước, tưới lá và quanh gốc. Tưới vào sáng sớm hoặc chiều mát.', '["ra-re","cai-tao-dat","phuc-hoi-cay-yeu"]'::jsonb, '["moi"]'::jsonb, true,
  'LASTING Kháng Nấm – Tuyến Trùng hỗ trợ kiểm soát nấm bệnh và tuyến trùng, đồng thời giúp cây phát triển bộ rễ khỏe, phục hồi sau giai đoạn bị ảnh hưởng và cải thiện môi trường đất. Hữu cơ an toàn — lành tính — phù hợp sử dụng cho nhiều loại cây trồng.

Sản phẩm giúp tăng sức đề kháng cho cây trồng, chống các chủng nấm và vi khuẩn có hại như nấm Phytophthora, nấm Fusarium và tuyến trùng gây nứt thân xì mủ, nấm phấn hồng, đồng thời ngăn ngừa bệnh hại như sùng, hà cho cây khoai lang.', '[{"label":"VSV phân giải Xenllulo","value":"1x10⁸ CFU/ml"},{"label":"Vi sinh vật có lợi","value":"Bacillus, Trichoderma, Enzyme"},{"label":"Thảo dược truyền thống","value":"Có"},{"label":"Thể tích thực","value":"1 lít"}]'::jsonb, 'Thông tin thành phần được trình bày theo công bố trên bao bì sản phẩm.', '["Tăng sức đề kháng cho cây trồng, chống các chủng nấm và vi khuẩn có hại như nấm Phytophthora, nấm Fusarium.","Kháng tuyến trùng gây nứt thân xì mủ, nấm phấn hồng.","Giúp cây có nội vi sinh chống lại các điều kiện thời tiết bất thường.","Ngăn ngừa bệnh hại như sùng, hà cho cây khoai lang.","Hỗ trợ phát triển bộ rễ khỏe, khử phèn và cải tạo đất."]'::jsonb, '["Lắc đều chai Lasting trước khi pha.","Pha theo liều lượng ở bảng dưới tùy nhóm cây trồng.","Tưới ướt đẫm vùng bị nấm/tuyến trùng, nứt thân, xì mủ để vi sinh dễ lưu dẫn.","Dưới mặt đất, dùng dụng cụ hỗ trợ (cây ba chĩa) xăm đều quanh gốc và dưới tán lá để tạo đường dẫn cho vi sinh thẩm thấu.","Cây thân gỗ không cần cạo vỏ khi tưới, chỉ cần tưới đẫm vùng cổ rễ, nơi nứt thân xì mủ và dưới tán lá.","Tưới vào sáng sớm hoặc chiều mát. Không pha chung với thuốc trừ sâu, thuốc có gốc đồng."]'::jsonb, '[{"crop":"Cây thân gỗ (sầu riêng, chè, cà phê)","dosage":"1 lít / 100–200 lít nước, tưới lá và xung quanh gốc"},{"crop":"Cây rau màu, cây thân dây (hồ tiêu, chanh dây, khổ qua, bầu bí, dưa, khoai lang, các loại đậu...)","dosage":"1 lít / 200–400 lít nước, tưới lá và xung quanh gốc"}]'::jsonb,
  '["Nơi khô ráo, thoáng mát, tránh ánh nắng trực tiếp.","Đậy nắp sau khi sử dụng.","Lắc đều trước khi pha.","Hạn sử dụng: 24 tháng kể từ ngày sản xuất, 6 tháng sau khi mở nắp.","Sau khi pha với nước: không để dung dịch quá 7 ngày."]'::jsonb, 'Không pha chung với thuốc trừ sâu hoặc thuốc có gốc đồng. Có thể điều chỉnh liều lượng phù hợp với tình trạng cây trồng, thổ nhưỡng đất canh tác và kinh nghiệm thực tế của người trồng.

Hiệu quả sử dụng sản phẩm có thể thay đổi tùy theo loại cây, tình trạng đất, điều kiện thời tiết, kỹ thuật canh tác và cách sử dụng thực tế. Khách hàng nên đọc kỹ hướng dẫn trên bao bì trước khi sử dụng.

Thông tin trên website chỉ có tính chất tham khảo và không thay thế hướng dẫn chính thức trên bao bì sản phẩm.', '{"thanhPhan":"VSV Xenllulo, Bacillus, Trichoderma","xuatXu":"Việt Nam","quyCach":"Chai 1 Lít","dang":"Dạng lỏng","congDung":"Kháng nấm, tuyến trùng, bật rễ","baoQuan":"Nơi khô ráo, đậy nắp sau dùng"}'::jsonb, '[{"icon":"Shield","title":"Kháng nấm, tuyến trùng","text":"Chống các chủng nấm Phytophthora, Fusarium và tuyến trùng gây nứt thân xì mủ."},{"icon":"Droplets","title":"Khử phèn, cải tạo đất","text":"Góp phần cải thiện môi trường đất chua phèn, tạo điều kiện tốt cho cây trồng."},{"icon":"Sprout","title":"Phát triển bộ rễ khỏe","text":"Hỗ trợ cây phát triển bộ rễ khỏe, phục hồi sau giai đoạn bị ảnh hưởng."},{"icon":"Leaf","title":"Tăng sức đề kháng","text":"Giúp cây có nội vi sinh chống lại các điều kiện thời tiết bất thường."}]'::jsonb, '[{"icon":"AlertCircle","title":"Nứt thân, xì mủ","desc":"Phù hợp khi cây (đặc biệt sầu riêng) có dấu hiệu nứt thân, xì mủ do nấm hoặc tuyến trùng."},{"icon":"Shield","title":"Nhiễm nấm Phytophthora, Fusarium","desc":"Hỗ trợ kiểm soát các chủng nấm gây hại phổ biến trên cây ăn trái, cây công nghiệp."},{"icon":"Sprout","title":"Bộ rễ suy yếu","desc":"Phù hợp khi cây cần phục hồi bộ rễ sau giai đoạn bị nấm, tuyến trùng tấn công."},{"icon":"Leaf","title":"Đất nhiễm phèn","desc":"Hỗ trợ khử phèn và cải tạo môi trường đất cho cây trồng."},{"icon":"Droplets","title":"Khoai lang bị sùng, hà","desc":"Ngăn ngừa bệnh hại như sùng, hà thường gặp trên cây khoai lang."}]'::jsonb, '{"nhomSanPham":"Chế phẩm sinh học bảo vệ rễ / cải tạo đất","quyCach":"Chai 1 Lít","dangSanPham":"Dung dịch lỏng","xuatXu":"Việt Nam"}'::jsonb
)
