) values (
  'bumper-duong', 'Bumper Dưỡng Trái', 'npk', '["lua","rau-mau","cay-an-trai","cay-cong-nghiep"]'::jsonb, 'Chai 1 Lít', 'nuoc', 117000, 130000,
  '/products/bumper-duong/img-1.png', '["/products/bumper-duong/gallery/img-1.png","/products/bumper-duong/gallery/img-2.png","/products/bumper-duong/gallery/img-3.png","/products/bumper-duong/gallery/img-4.png","/products/bumper-duong/gallery/img-5.png","/products/bumper-duong/gallery/img-6.png","/products/bumper-duong/gallery/img-7.png","/products/bumper-duong/gallery/img-8.png","/products/bumper-duong/gallery/img-9.png","/products/bumper-duong/gallery/img-10.png"]'::jsonb, 'Chế phẩm sinh học dưỡng trái giúp trái lớn nhanh, căng bóng, nặng ký, tăng độ ngọt tự nhiên và đồng đều.', 'VSV phân giải Xenllulo 0,1x10⁸ CFU/ml; Nguyên liệu: đạm tôm, bánh dầu, rong biển, nha đam; Vi sinh chuyên dùng: Bacillus, Trichoderma, Enzyme', 'Cây trồng lâu năm (sầu riêng, điều, chè, cà phê, ca cao, xoài, bưởi, thanh long...): 1 lít/200-400 lít nước, tưới gốc 10-15 lít/cây trưởng thành (5-10 lít/cây nhỏ), chu kỳ 15-20 ngày/lần. Cây thân dây: 1 lít/400-600 lít nước, chu kỳ 10-15 ngày/lần. Cây rau màu: 1 lít/600-800 lít nước, chu kỳ 7-10 ngày/lần.', '["nuoi-trai","duong-cay"]'::jsonb, '["moi"]'::jsonb, true,
  'BUMPER Dưỡng Trái bổ sung dưỡng chất giúp nuôi trái lớn nhanh, căng bóng, nặng ký — tăng độ ngọt tự nhiên — trái đồng đều, nâng cao giá trị nông sản. Giải pháp sinh học an toàn, hiệu quả cho cây trồng và đất canh tác lâu dài, hữu cơ an toàn — lành tính.

Chuyên dùng cho cây công nghiệp, dược liệu, cây ăn quả, cây lương thực, lúa và rau củ quả — thúc đẩy quá trình sinh trưởng, tổng hợp trao đổi chất, tăng sức đề kháng và giảm tỷ lệ thất thoát nông sản.', '[{"label":"VSV phân giải Xenllulo","value":"0,1x10⁸ CFU/ml"},{"label":"Nguyên liệu","value":"Đạm tôm, bánh dầu, rong biển, nha đam"},{"label":"Vi sinh chuyên dùng","value":"Bacillus, Trichoderma, Enzyme"},{"label":"Thể tích thực","value":"1 lít"}]'::jsonb, 'Thông tin thành phần được trình bày theo công bố trên bao bì sản phẩm.', '["Thúc đẩy quá trình sinh trưởng, tổng hợp trao đổi chất cho các loại cây và củ.","Tăng sức đề kháng, giúp cây phát triển, củ và trái to, sáng bóng, có trọng lượng.","Tăng hương vị tự nhiên, trái ngọt và đồng đều hơn.","Giảm tỷ lệ thất thoát nông sản."]'::jsonb, '["Lắc đều chai Bumper Dưỡng Trái trước khi pha.","Tưới nước trước cho cây ẩm ướt để tạo đường dẫn cho vi sinh thẩm thấu.","Pha và tưới gốc theo đúng nhóm cây, liều lượng và chu kỳ ở bảng dưới.","Tưới vào sáng sớm hoặc chiều mát.","Không pha chung với thuốc trừ sâu, thuốc có gốc đồng."]'::jsonb, '[{"crop":"Cây trồng lâu năm (sầu riêng, điều, chè, cà phê, ca cao, xoài, bưởi, thanh long...) — cây trưởng thành","dosage":"Pha 1 lít/200–400 lít nước, tưới gốc 10–15 lít dung dịch/cây, chu kỳ 15–20 ngày/lần"},{"crop":"Cây trồng lâu năm — cây vừa và nhỏ","dosage":"Pha 1 lít/200–400 lít nước, tưới gốc 5–10 lít dung dịch/cây, chu kỳ 15–20 ngày/lần"},{"crop":"Cây thân dây (hồ tiêu, chanh dây, bầu, bí, khổ qua, ớt, các loại dưa, khoai lang...)","dosage":"Pha 1 lít/400–600 lít nước, tưới gốc 50–100 lít/1.000m², chu kỳ 10–15 ngày/lần"},{"crop":"Cây rau màu (bắp cải, xà lách, các loại cải, rau thơm, cây gia vị, hành lá...)","dosage":"Pha 1 lít/600–800 lít nước, tưới gốc 40–60 lít/1.000m², chu kỳ 7–10 ngày/lần"}]'::jsonb,
  '["Nơi khô ráo, thoáng mát, tránh ánh nắng trực tiếp.","Đậy nắp sau khi sử dụng.","Lắc đều trước khi pha.","Hạn sử dụng: 24 tháng kể từ ngày sản xuất, 6 tháng sau khi mở nắp.","Sau khi pha với nước: không để dung dịch quá 7 ngày."]'::jsonb, 'Không pha chung với thuốc trừ sâu hoặc thuốc có gốc đồng. Có thể điều chỉnh liều lượng phù hợp với tình trạng cây trồng, thổ nhưỡng đất canh tác và kinh nghiệm thực tế của người trồng.

Hiệu quả sử dụng sản phẩm có thể thay đổi tùy theo loại cây, tình trạng đất, điều kiện thời tiết, kỹ thuật canh tác và cách sử dụng thực tế. Khách hàng nên đọc kỹ hướng dẫn trên bao bì trước khi sử dụng.

Thông tin trên website chỉ có tính chất tham khảo và không thay thế hướng dẫn chính thức trên bao bì sản phẩm.', '{"thanhPhan":"VSV Xenllulo, đạm tôm, rong biển","xuatXu":"Việt Nam","quyCach":"Chai 1 Lít","dang":"Dạng lỏng","congDung":"Dưỡng trái, to trái, ngọt trái","baoQuan":"Nơi khô ráo, đậy nắp sau dùng"}'::jsonb, '[{"icon":"Sun","title":"To trái, căng bóng","text":"Giúp trái lớn nhanh, căng bóng, nặng ký và có trọng lượng tốt hơn."},{"icon":"Zap","title":"Tăng độ ngọt tự nhiên","text":"Hỗ trợ tổng hợp trao đổi chất giúp trái tăng hương vị và độ ngọt tự nhiên."},{"icon":"Sprout","title":"Trái đồng đều","text":"Góp phần giúp trái phát triển đồng đều trên toàn bộ cây trồng."},{"icon":"Leaf","title":"Giảm thất thoát","text":"Tăng sức đề kháng cho cây, giúp giảm tỷ lệ thất thoát nông sản."}]'::jsonb, '[{"icon":"Sun","title":"Giai đoạn nuôi trái","desc":"Phù hợp sử dụng đúng giai đoạn cây đang nuôi trái, cần bổ sung dưỡng chất."},{"icon":"Zap","title":"Trái nhỏ, chưa đều","desc":"Hỗ trợ khi trái phát triển không đều hoặc kích thước chưa đạt kỳ vọng."},{"icon":"Leaf","title":"Muốn nâng chất lượng","desc":"Phù hợp khi muốn cải thiện độ ngọt, trọng lượng và hương vị nông sản trước thu hoạch."},{"icon":"Sprout","title":"Cây ăn trái, cây lâu năm","desc":"Thích hợp cho sầu riêng, xoài, bưởi, thanh long và các cây ăn trái khác trong giai đoạn nuôi trái."},{"icon":"AlertCircle","title":"Tỷ lệ thất thoát cao","desc":"Hỗ trợ giảm tỷ lệ thất thoát nông sản nhờ tăng sức đề kháng cho cây."}]'::jsonb, '{"nhomSanPham":"Chế phẩm sinh học dưỡng trái","quyCach":"Chai 1 Lít","dangSanPham":"Dung dịch lỏng","xuatXu":"Việt Nam"}'::jsonb
)
